  ('timberline-mt-hood-oregon', '12A', 'Timberline Lodge / Mt. Hood', 'United States', 'The only place in America you can ski every', 'live', 'verified', 'northernLights', 'Pacific Northwest', '{"ski","ultra","romance","culinary","family","wellness"}', '{}', '{"essential","comfort","premier","luxury","ultra"}', null, 'core', '{"key_facts":["The only year-round ski area in the US — Palmer Snowfield/Glacier lift-served ~Jun-Aug (Palmer upper terminal ~8,500 ft; base/lodge ~5,960-6,000 ft)","Official SUMMER training site of the US Ski & Snowboard Teams (GS, slalom, moguls, skier/snowboardcross + World Cup start gate) + Freestyle Training Center; biggest summer camp scene in North America","Timberline Lodge = National Historic Landmark, built 1936-38 by the WPA, dedicated by FDR 28 Sept 1937; Overlook Hotel exterior in ''The Shining'' (1980)","Independent — Mt. Hood Fusion Pass (Timberline + Summit Pass + Skibowl, Powder Alliance); NOT Epic/Ikon","Mt. Hood = active glaciated stratovolcano (summit 11,249 ft); Palmer glaciated — crevasse hazard above the lift","~60 mi east of Portland on US-26 (Government Camp); PDX ~1.5 hr; NWAC covers the zone; nearest hospitals Providence Hood River / Legacy Mount Hood Medical Center (Gresham)"],"safety":{"emergency":"911 (police/fire/ambulance/rescue dispatch, nationwide)","hospital":"on-mountain ski patrol in season; nearest hospitals Providence Hood River Memorial + Legacy Mount Hood Medical Center (Gresham, 24/7 ER); serious cases to Portland trauma centers; summit rescue via Clackamas County Sheriff + Portland Mountain Rescue / 911","malaria":"none","yellow_fever":"not required","activity_note":"UPPER-MOUNTAIN EXPOSURE + FAST WHITEOUT (Hood notorious; 1986 OES tragedy) turn back early; GLACIER/CREVASSE hazard on Palmer + summit (11,249 ft = roped guided mountaineering only); AVALANCHE beyond ropes (check NWAC, guide + beacon/probe/shovel); Cascade winter driving + ODOT chain control (US-26/TripCheck); moderate altitude (base ~5,960 ft, Palmer ~8,500 ft); tree wells; cold + fast Pacific storms"},"timing":{"peak":"High winter (Christmas/NY, MLK + Presidents'' wknds, Feb) ski + powder; SECOND peak Jul-Aug (Palmer summer glacier skiing + camp season — one of a kind)","shoulder":"early season (Nov-mid Dec), Jan weekdays, Apr-May spring, Jun/Sep (summer camp season open/close)","green":"Oct-mid Nov (brief lull between summer-glacier wind-down and full winter open; some ops reduced — verify)","booking_lead":"Christmas/NY + summer camp weeks + historic Timberline Lodge rooms/suites 4-10 mo; Presidents''/Feb 3-6 mo; Palmer summer ski 1-4 mo; shoulder/powder 1-6 wk","off_season_specials":"SUMMER glacier ski/camp weeks (Jun-Aug) — signature engine, no other US resort sells July skiing; spring-corn ski (Apr-May); year-round historic-lodge stay","event_peaks":"Christmas/NY, MLK + Presidents'' wknds, US school half-terms, summer camp sessions (Jun-Aug), spring closing (verify 2027)","campaign_start":"FIRE ski mid-late Mar + late Aug-early Sep; THIRD inflection — summer-glacier + camp campaign Jan-Mar (Jun-Aug Palmer weeks)"},"jewels":[{"name":"Ski a glacier in July — the only year-round skiing in America","si_tag":"Winter / Ski","status":"future","tier":"comfort","price_band":"Palmer summer ticket; camps separate","timing":"~Jun-Aug — snow-dependent, verify Palmer dates","draw_rank":1,"hook":"ride the Palmer chairlift onto the summer snowfield and ski in a T-shirt June through August","si":"Winter / Ski","blurb":"ride the Palmer chairlift onto the summer snowfield and ski in a T-shirt June through August","when":"~Jun-Aug — snow-dependent, verify Palmer dates","commission":"DMC/ski-op 10-20% (embedded-capable)"},{"name":"Train where the US team trains — the summer camp scene","si_tag":"Winter / Ski","status":"future","tier":"comfort","price_band":"multi-day camp sessions","timing":"~Jun-Aug — FIRE bookings Jan-Mar","draw_rank":2,"hook":"freestyle, race and youth camps on the same groomed lanes the US Ski 